import{z as d,x as h,o as t,c as m,q as l,j as r,D as n,d as o,s,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const O=JSON.parse('{"title":"渐近记号","description":"","frontmatter":{"title":"渐近记号","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/asymptotic-notation.md","filePath":"cs/asymptotic-notation.md","lastUpdated":1791063341000}'),c={name:"cs/asymptotic-notation.md"};function E(T,a,u,f,B,_){const i=h("Mermaid");return t(),m("div",null,[a[2]||(a[2]=l('<h1 id="渐近记号" tabindex="-1">渐近记号 <a class="header-anchor" href="#渐近记号" aria-label="Permalink to &quot;渐近记号&quot;">​</a></h1><div class="epigraph"><p>只关心 $n$ 足够大以后增长速度的上界、下界和紧界，常数与低次项都收进记号里。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms, 第 3 章 整理</footer></div><p>上一课<a href="/cs/inclusion-exclusion">容斥</a>钉死了如何对每个 \\(n\\) 证明 \\(P(n)\\)。本课不重写基础步，也不从「算法是什么」另起。缺口是：归纳可以证明循环做对了，还没有语言说「做完要多久」。后课图算法、排序，必须比较增长，而不是比较某台机器上的秒数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两段程序都对，一段嵌套循环，一段分治。常数因子依赖实现，本栏不把计时当定义。缺口因此不是新的证明格式，而是 CLRS 第 3 章那套：\\(O\\) 是渐近上界，\\(\\Omega\\) 是下界，\\(\\Theta\\) 是同阶，\\(o\\) 与 \\(\\omega\\) 是非紧的。定义用存在常数 \\(c\\)、\\(n_0\\)，使 \\(n\\ge n_0\\) 后不等式成立。</p><p>本课只钉记号与常见多项式、对数、指数的比较。主定理、分治递归式是很后面算法课的叶子，这里不预支。</p><h3 id="不是「最坏情况」" tabindex="-1">\\(O\\) 不是「最坏情况」 <a class="header-anchor" href="#不是「最坏情况」" aria-label="Permalink to &quot;$O$ 不是「最坏情况」&quot;">​</a></h3><p>\\(O\\) 是函数之间的关系，可以说某算法最坏运行时间是 \\(O(n^2)\\)，但 \\(O\\) 本身不管输入分布。把「平均 \\(O\\)」与「最坏 \\(O\\)」混成一个词，后课快排会说不清。也不把 \\(O(n^2)\\) 当成「恰好平方」：那是 \\(\\Theta\\)。</p><p><span class="marginnote">CLRS 强调记号描述的是函数，不是算法。本课的 \\(T(n)\\) 先当作给定的非负函数；如何从代码读出 \\(T\\)，后课循环与递归再做。</span></p><p><span class="marginnote">直觉类比：\\(\\Theta\\) 是「同尺码」——存在常数 \\(c\\) 让两边互相夹住，只差常数倍；\\(O\\) 是「不超过这个尺码」，是宽松上界——线性算法当然也算 \\(O(n^2)\\)，就像身高 170 的人也「不超过 190」；说「恰好同阶」必须用 \\(\\Theta\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(f(n)=O(g(n))\\) 当存在 \\(c\\gt 0\\)、\\(n_0\\)，使 \\(n\\ge n_0\\) 时 \\(0\\le f(n)\\le c\\,g(n)\\)。\\(\\Theta\\) 则上下同时夹住。多项式：最高次项决定 \\(\\Theta\\)。\\(\\log n\\) 增长慢于任何正幂；\\(2^n\\) 快于任何多项式。证明用极限或归纳不等式，不在本课把 Stirling 全写开。</p><p><span class="marginnote">数字实例：\\(n=1000\\) 时各阶差出天壤——\\(\\log_2 n\\approx 10\\)，\\(n^2=10^6\\)，\\(2^n\\) 是一个 301 位的十进制数。若一步算 1 纳秒：对数阶 10 纳秒，平方阶 1 毫秒，指数阶跑完比宇宙年龄还长得多。这就是后课敢把「平方排序」扔掉的底气。</span></p>',13)),(t(),r(p,null,{default:n(()=>[s(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22T(n)%20%E9%9D%9E%E8%B4%9F%22%5D%20--%3E%20O%5B%22O%20%E4%B8%8A%E7%95%8C%22%5D%0A%20%20T%20--%3E%20OM%5B%22%CE%A9%20%E4%B8%8B%E7%95%8C%22%5D%0A%20%20O%20--%3E%20TH%5B%22%CE%98%20%E7%B4%A7%E7%95%8C%22%5D%0A%20%20OM%20--%3E%20TH%0A%20%20TH%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%9B%BE%E4%B8%8A%E7%9A%84%20T(n)%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"有了记号，后课才能写「邻接表上 BFS 是 \\(\\Theta(V+E)\\)」而不绑定时钟频率。机器字长、比特操作的常数，在 RAM 模型里常被收进 \\(O\\) 的 \\(c\\)。本栏组成课稍后会把周期数与门延迟写具体；与本课不冲突：一个是渐近，一个是纳秒。",-1)),a[5]||(a[5]=e("p",null,"多变量代价（图的 \\(V,E\\)）把 \\(n\\) 换成几个参数，记号仍适用，须声明对哪些量取极限。",-1)),a[6]||(a[6]=e("p",null,"后课最常用的几个阶，从慢到快怎么排队、\\(n\\) 变大时谁压过谁：",-1)),(t(),r(p,null,{default:n(()=>[s(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20L%5B%22log%20n%22%5D%20--%3E%20P1%5B%22n%22%5D%20--%3E%20NL%5B%22n%20log%20n%22%5D%20--%3E%20P2%5B%22n%C2%B2%22%5D%20--%3E%20E%5B%222%E2%81%BF%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">常见误区：初学者容易以为「渐近阶小的实现永远更快」。常数在小 \\(n\\) 时能压过阶：每步 100 的线性算法在 \\(n=10\\) 时要 1000 步，而朴素平方只要 100 步，直到 \\(n\\) 过百才被反超——库里的排序小段用插入排序，正是这个道理。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入摊还、期望运行时间的形式化——后者要等<a href="/cs/discrete-probability">离散概率</a>之后，快排那课才用。也不把 NP 的多项式时间定义提前。小 \\(n\\) 时常数可以压过渐近，工程选择不由本课独断。</p><p>后课默认：比较算法代价用 \\(\\Theta\\)、\\(O\\)、\\(\\Omega\\)；说「平方级」默认 \\(\\Theta(n^2)\\) 除非另注。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(O\\)、\\(\\Omega\\)、\\(\\Theta\\) 比较增长，藏起常数与低次项。</li><li>\\(O\\) 不是最坏/平均的同义词；\\(\\Theta\\) 才是同阶。</li><li>对数、多项式、指数的阶已经够后课排序与图。</li><li>出处：CLRS 第 3 章。</li></ul>',6))])}const A=d(c,[["render",E]]);export{O as __pageData,A as default};
